-- composition of rule kernels empty_result_pullup x statistics_propagation (duckdb), template cte_twice
WITH ka AS (SELECT 20 AS c0, a1.c5 AS c1, 'A'::text AS c2, 1000::bigint AS c3 FROM t3 AS a1 GROUP BY a1.c2, a1.c5), kb AS (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT FALSE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2 UNION (SELECT FALSE AS c0, TRUE AS c1, []::text[] AS c2 FROM t4 AS a1 WHERE NULL::boolean EXCEPT (SELECT FALSE AS c0, FALSE AS c1, ARRAY['1'::text] AS c2 UNION SELECT TRUE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2))) SELECT (SELECT count(*) FROM ka) + (SELECT count(*) FROM kb) + (SELECT count(*) FROM ka);
-- pgfuzz:check kernel:cte_twice SELECT 2 * (SELECT count(*) FROM (SELECT 20 AS c0, a1.c5 AS c1, 'A'::text AS c2, 1000::bigint AS c3 FROM t3 AS a1 GROUP BY a1.c2, a1.c5) AS ka) + (SELECT count(*) FROM (WITH RECURSIVE rc(c0) AS (SELECT 1 UNION ALL SELECT r.c0 + 1 FROM rc AS r WHERE r.c0 < 5) SELECT FALSE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2 UNION (SELECT FALSE AS c0, TRUE AS c1, []::text[] AS c2 FROM t4 AS a1 WHERE NULL::boolean EXCEPT (SELECT FALSE AS c0, FALSE AS c1, ARRAY['1'::text] AS c2 UNION SELECT TRUE AS c0, TRUE AS c1, ARRAY['1'::text] AS c2))) AS kb)
